DECLARE @ID_84f14e694501 UNIQUEIDENTIFIER,
@Name_84f14e694501 NVARCHAR(255),
@CategoryID_84f14e694501 UNIQUEIDENTIFIER,
@UserQuestion_84f14e694501 NVARCHAR(MAX),
@Description_84f14e694501 NVARCHAR(MAX),
@SQL_84f14e694501 NVARCHAR(MAX),
@TechnicalDescription_84f14e694501 NVARCHAR(MAX),
@OriginalSQL_84f14e694501 NVARCHAR(MAX),
@Feedback_84f14e694501 NVARCHAR(MAX),
@Status_84f14e694501 NVARCHAR(15),
@QualityRank_84f14e694501 INT,
@ExecutionCostRank_84f14e694501 INT,
@UsesTemplate_84f14e694501 BIT,
@AuditQueryRuns_84f14e694501 BIT,
@CacheEnabled_84f14e694501 BIT,
@CacheTTLMinutes_84f14e694501 INT,
@CacheMaxSize_84f14e694501 INT,
@EmbeddingVector_84f14e694501 NVARCHAR(MAX),
@EmbeddingModelID_84f14e694501 UNIQUEIDENTIFIER,
@CacheValidationSQL_84f14e694501 NVARCHAR(MAX),
@SQLDialectID_84f14e694501 UNIQUEIDENTIFIER,
@Reusable_84f14e694501 BIT,
@ExternalDataSourceID_84f14e694501 UNIQUEIDENTIFIER,
@IsMaterialized_84f14e694501 BIT,
@Configuration_84f14e694501 NVARCHAR(MAX)
SET
  @ID_84f14e694501 = '7C9243A8-0B86-4CFA-A3DF-9A0E50FBC605'
SET
  @Name_84f14e694501 = N'AIUsageByUser'
SET
  @CategoryID_84f14e694501 = '6C8C5BA5-D9D1-47A1-8EF8-E59DA57F9D22'
SET
  @UserQuestion_84f14e694501 = N'What is our AI usage, spend, and token volume per user for chargeback attribution?'
SET
  @Description_84f14e694501 = N'Aggregates AI usage facts by UserID to support user-level chargeback, attribution, and consumption monitoring.'
SET
  @SQL_84f14e694501 = N'-- AI usage per user (+ currency). Live-only.
--
-- Rows are model calls: parallel parents are excluded (their arms carry the work and the cost).
-- Cost is grouped by CostCurrency so two currencies are never summed into one unitless number, and
-- PricedRuns / UnpricedRuns travel beside it — an unpriced run is excluded from OwnCost, not zero.
-- The window filters the base RunAt column (range-seekable on IX_AIPromptRun_RunAt).
SELECT
    UserID,
    CostCurrency,
    COUNT(*) AS Runs,
    SUM(CASE WHEN IsPriced = 1 THEN 1 ELSE 0 END) AS PricedRuns,
    SUM(CASE WHEN IsPriced = 0 THEN 1 ELSE 0 END) AS UnpricedRuns,
    SUM(CASE WHEN IsPriced = 1 THEN OwnCost ELSE 0 END) AS OwnCost,
    SUM(TokensPrompt) AS TokensPrompt,
    SUM(TokensCompletion) AS TokensCompletion,
    MAX(RunAtUTC) AS LastRunAt
FROM [${flyway:defaultSchema}].vwAIUsageFacts
WHERE IsCompleted = 1
  AND IsParallelParent = 0
  {% if start %}
  AND RunAt >= {{ start | sqlDate }}
  {% endif %}
  {% if end %}
  AND RunAt < {{ end | sqlDate }}
  {% endif %}
GROUP BY
    UserID,
    CostCurrency
