SET
  @ID_d8fe9e629d26 = '226484B9-8178-418A-8CDB-25D2BF234684'
SET
  @Name_d8fe9e629d26 = N'AIUsageUnpricedAudit'
SET
  @CategoryID_d8fe9e629d26 = '6C8C5BA5-D9D1-47A1-8EF8-E59DA57F9D22'
SET
  @UserQuestion_d8fe9e629d26 = N'Which completed AI runs have not been priced and need pricing tiers or investigation?'
SET
  @Description_d8fe9e629d26 = N'Surfaces completed AI prompt runs where IsPriced = 0 (parallel parents excluded), newest first, with a diagnostic explanation for why each run was unpriced (unmeasured, or missing pricing tier).'
SET
  @SQL_d8fe9e629d26 = N'-- Completed prompt runs that carry no cost, newest first, for an admin backfilling price tiers.
-- Live-only.
--
-- BOUNDED: an optional RunAt window (range-seekable on IX_AIPromptRun_RunAt) and a row cap
-- (maxRows, default 500). Ordered by the base RunAt column, which the same index serves in order,
-- rather than a derived UTC expression that forces a sort of every unpriced run in history.
SELECT TOP ({% if maxRows %}{{ maxRows | sqlNumber }}{% else %}500{% endif %})
    PromptRunID,
    AgentRunID,
    ParentPromptRunID,
    RunAt,
    RunAtUTC,
    PromptID,
    ModelID,
    VendorID,
    AgentID,
    ConfigurationID,
    UserID,
    ConversationID,
    PrimaryScopeEntityID,
    PrimaryScopeRecordID,
    RunType,
    SourceKind,
    Status,
    Success,
    TokensPrompt,
    TokensCompletion,
    TokensCacheRead,
    TokensCacheWrite,
    InputUnitsUsed,
    OutputUnitsUsed,
    ExecutionTimeMS,
    IsUnmeasured,
    CASE
        WHEN IsUnmeasured = 1 THEN ''Unmeasured run: no token or unit counts recorded''
        ELSE ''Missing pricing: no price tier found for model at run time''
    END AS UnpricedReason
FROM [${flyway:defaultSchema}].vwAIUsageFacts
WHERE IsCompleted = 1
  AND IsPriced = 0
  -- A parallel parent has no own cost BY DESIGN (the arms carry it), so it is not "unpriced".
  -- Without this it lands in an admin-facing "needs a price tier" list and sends someone hunting
  -- for a tier that was never missing.
  AND IsParallelParent = 0
  {% if start %}
  AND RunAt >= {{ start | sqlDate }}
  {% endif %}
  {% if end %}
  AND RunAt < {{ end | sqlDate }}
  {% endif %}
ORDER BY
    RunAt DESC
'
SET
  @TechnicalDescription_d8fe9e629d26 = N'Quality and audit query over [${flyway:defaultSchema}].vwAIUsageFacts for IsCompleted = 1 AND IsPriced = 0 AND IsParallelParent = 0, bounded by an optional start/end window on the base RunAt column and a row cap (maxRows, default 500), ordered by RunAt descending. Emits UnpricedReason to assist administrators in backfilling model cost configurations.'
SET
  @Status_d8fe9e629d26 = N'Approved'
