@ID_9a8cf052a7c8 UNIQUEIDENTIFIER
SET
  @Name_9a8cf052a7c8 = N'CalculateRunCost'
SET
  @CategoryID_9a8cf052a7c8 = '5609FBC7-381C-4F9C-9C74-04B52C1FF3DA'
SET
  @UserQuestion_9a8cf052a7c8 = N'What is the total cost, token usage, and number of prompts for an AI Agent Run including all its sub-agent runs?'
SET
  @Description_9a8cf052a7c8 = N'Calculates comprehensive cost metrics for an AI Agent Run, including all nested sub-agent runs. Returns total cost, token usage (input/output), and prompt count by recursively traversing the agent run hierarchy.'
SET
  @SQL_9a8cf052a7c8 = N'-- Calculate AI Agent Run Cost with Recursive Sub-Agent Hierarchy
WITH AgentRunHierarchy AS (
  -- Base case: Start with the specified agent run
  SELECT ID, AgentID, ParentRunID, 1 as Level
  FROM [${flyway:defaultSchema}].vwAIAgentRuns
  WHERE ID = TRY_CONVERT(uniqueidentifier, {{ AIAgentRunID | sqlString }}) -- Replace with the actual Agent Run ID parameter. This is a UUID.
  
  UNION ALL
  
  -- Recursive case: Get all child agent runs
  SELECT ar.ID, ar.AgentID, ar.ParentRunID, arh.Level + 1
  FROM [${flyway:defaultSchema}].vwAIAgentRuns ar
  INNER JOIN AgentRunHierarchy arh ON ar.ParentRunID = arh.ID
  WHERE arh.Level < 20  -- Prevent infinite recursion
)
SELECT 
  {{ AIAgentRunID | sqlString }} AS AgentRunID,
  SUM(CASE WHEN f.IsPriced = 1 AND f.IsParallelParent = 0 THEN f.OwnCost END) AS TotalCost,
  SUM(CASE WHEN f.IsParallelParent = 0 THEN 1 ELSE 0 END) AS TotalPrompts,
  SUM(CASE WHEN f.IsParallelParent = 0 THEN f.TokensPrompt ELSE 0 END) AS TotalTokensInput,
  SUM(CASE WHEN f.IsParallelParent = 0 THEN f.TokensCompletion ELSE 0 END) AS TotalTokensOutput,
  SUM(CASE WHEN f.IsParallelParent = 0 THEN f.TokensPrompt + f.TokensCompletion ELSE 0 END) AS TotalTokens
FROM [${flyway:defaultSchema}].vwAIUsageFacts f
INNER JOIN AgentRunHierarchy arh ON f.AgentRunID = arh.ID
WHERE f.IsCompleted = 1
'
SET
  @TechnicalDescription_9a8cf052a7c8 = N'This query uses a Common Table Expression (CTE) to recursively traverse the AI Agent Run hierarchy, starting from a specified root agent run and including all nested sub-agent runs up to 20 levels deep. It then joins with AI Agent Run Steps to find all prompt executions and calculates aggregate cost and token metrics. The query uses template parameters for the MJ Core schema name and agent run ID to ensure compatibility across different environments.'
SET
  @Status_9a8cf052a7c8 = N'Approved'
